# ---- id 853-872 ----
T[853] = "Teufel auf den Ebenen 4 bis 6 des Verlorenen Turms sollten ausreichen. Geh zum Verlorenen Turm und besiege 100 Teufel. Komm danach zu mir, dann gebe ich dir eine Wahl zwischen 15 SD-Tränken und 15 Komplex-Tränken als Belohnung. Wenn du deine Belohnung abholst, stelle sicher, dass du mindestens 15 leere Plätze im Inventar hast. Merk dir das."
T[854] = "Hast du das Charakterstatus-Fenster geöffnet?;Dieses Fenster enthält den Namen und das Level des Charakters, den Namen des aktuellen Servers und die Charakterwerte."
T[855] = "Hast du die Leertaste gesagt?"
T[860] = "Beseitige den Anführer der Plünderer!"
T[861] = "Beseitige die Stadtplünderer!"
T[872] = "Klingt nicht allzu schwierig...."

# ---- id 927-954 ----
T[927] = "Dreadfears in den Kanturu-Relikten verursachen großen Schaden bei Reisenden dort. Geh zu den Kanturu-Relikten und jage 100 Dreadfears nieder. Komm zu mir, wenn das erledigt ist, um einen Unsichtbarkeitsumhang + 8 als Belohnung zu erhalten. Auf deinem jetzigen Level ist es zu gefährlich für dich, die Monster allein zu jagen. Besser in einer Gruppe."
T[928] = "Doch aufgrund von Levs Illusionszaubern blieben die Seelen der toten Anhänger in dieser Welt, um den Tempel zu verteidigen. Diese Seelen glaubten, dass Levs Rückkehr ihnen die Körper zurückgeben würde – und sie bewachten den Tempel weiter. Heute wird der Tempel von der Allianz bewacht, falls Lev tatsächlich zurückkehrt – und Illusionszauberei nutzt antike Relikte, um ahnungslose Reisende für ihre Sache zu ködern."
T[937] = "Verlies-Säuberung!"
T[947] = "Dural, der erste Meister der Gilde, war ein legendärer Kommandeur, der uns zu einem großen Sieg gegen Kunduns Armee führte. Er musste sich seit Gaions Rebellion und dem Befehl zur Ausrottung der 5 großen Clans von der Welt zurückziehen. Die neu gegründete Söldnergilde hat jegliche Beziehungen zu Gaion abgebrochen – aber die 5 großen Clans wollen immer noch, dass die Söldnergilde Gaion beseitigt."
T[948] = "EXP-Punkte und Levelaufstieg"
T[954] = "Wertvolle Ausrüstung durch einfache Quests verdienen?"

